using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.IO;
using System.Linq;
using System.Net;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            TestHelpers.DrainNotificationQueue();
            _context = TestHelpers.CreateContext();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();

            _tempDir = Path.Combine(Path.GetTempPath(), "contoso_test_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempDir);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);

            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
            TestHelpers.SetupControllerContext(_controller);
        }

        public void Dispose()
        {
            TestHelpers.DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
            try { if (Directory.Exists(_tempDir)) Directory.Delete(_tempDir, true); } catch { }
        }

        private Department SeedDepartment()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        private Mock<IFormFile> CreateMockFile(string fileName, long size = 1024)
        {
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns(fileName);
            mockFile.Setup(f => f.Length).Returns(size);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => { });
            return mockFile;
        }

        #region Index

        [Fact]
        public void Index_ReturnsCoursesList()
        {
            // Arrange
            SeedCourse();

            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Chemistry", model[0].Title);
        }

        [Fact]
        public void Index_NoCourses_ReturnsEmptyList()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result.Model);
            Assert.Empty(model);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var course = SeedCourse();

            // Act
            var result = _controller.Details(course.CourseID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
            Assert.Equal(3, model.Credits);
        }

        #endregion

        #region Create

        [Fact]
        public void Create_GET_ReturnsViewWithDepartmentList()
        {
            // Arrange
            SeedDepartment();

            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
            Assert.IsType<Course>(result.Model);
        }

        [Fact]
        public void Create_POST_ValidCourseNoFile_RedirectsToIndex()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2000,
                Title = "New Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            // Act
            var result = _controller.Create(course, null!);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void Create_POST_WithValidImage_SavesFileAndRedirects()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3000,
                Title = "Art Course",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateMockFile("test.jpg");

            // Act
            var result = _controller.Create(course, mockFile.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Courses.Find(3000);
            Assert.NotNull(saved);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved!.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_POST_InvalidExtension_ReturnsViewWithError()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 4000,
                Title = "Bad File Course",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateMockFile("test.exe");

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Empty(_context.Courses);
        }

        [Fact]
        public void Create_POST_OversizedFile_ReturnsViewWithError()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 5000,
                Title = "Big File Course",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateMockFile("test.jpg", 6 * 1024 * 1024); // 6MB

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Empty(_context.Courses);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            // Arrange
            var course = new Course { CourseID = 6000, Title = "X", Credits = 1, DepartmentID = 1 };
            _controller.ModelState.AddModelError("Title", "Required");

            // Act
            var result = _controller.Create(course, null!) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Create_POST_ValidCourse_SendsNotification()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 7000,
                Title = "NotifyCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            // Act
            _controller.Create(course, null!);

            // Assert
            var svc = new Services.NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Contains("NotifyCourse", notification.Message);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_AllowedImageExtensions_Succeeds(string extension)
        {
            // Arrange
            var dept = SeedDepartment();
            var courseId = 8000 + Math.Abs(extension.GetHashCode() % 1000);
            var course = new Course
            {
                CourseID = courseId,
                Title = $"Course{extension}",
                Credits = 1,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateMockFile($"image{extension}");

            // Act
            var result = _controller.Create(course, mockFile.Object);

            // Assert
            Assert.IsType<RedirectToActionResult>(result);
        }

        #endregion

        #region Edit

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_NotFound_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsView()
        {
            // Arrange
            var course = SeedCourse();

            // Act
            var result = _controller.Edit(course.CourseID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
