        [Fact]
        public void Edit_POST_OversizedFile_ReturnsViewWithError()
        {
            // Arrange
            var course = SeedCourse();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Course
            {
                CourseID = course.CourseID,
                Title = "Updated",
                Credits = 3,
                DepartmentID = course.DepartmentID
            };
            var mockFile = CreateMockFile("big.jpg", 10 * 1024 * 1024);

            // Act
            var result = _controller.Edit(updated, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        #endregion

        #region Delete

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsView()
        {
            // Arrange
            var course = SeedCourse();

            // Act
            var result = _controller.Delete(course.CourseID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            // Arrange
            var course = SeedCourse();

            // Act
            var result = _controller.DeleteConfirmed(course.CourseID);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Courses);
        }

        [Fact]
        public void DeleteConfirmed_SendsNotification()
        {
            // Arrange
            var course = SeedCourse();

            // Act
            _controller.DeleteConfirmed(course.CourseID);

            // Assert
            var svc = new Services.NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
