using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            TestHelpers.DrainNotificationQueue();
            _context = TestHelpers.CreateContext();
            _controller = new InstructorsController(_context);
            TestHelpers.SetupControllerContext(_controller);
        }

        public void Dispose()
        {
            TestHelpers.DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor SeedInstructorWithCourses()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course1 = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID };
            var course2 = new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.AddRange(course1, course2);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11"),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" },
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1050 }
                }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            return instructor;
        }

        private Instructor SeedSimpleInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Roger",
                LastName = "Harui",
                HireDate = DateTime.Parse("1998-07-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        #region Index

        [Fact]
        public void Index_NoSelection_ReturnsInstructorsWithNoCoursesSelected()
        {
            // Arrange
            SeedInstructorWithCourses();

            // Act
            var result = _controller.Index(null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Instructors);
            Assert.Single(model.Instructors);
            Assert.Null(model.Courses);
            Assert.Null(model.Enrollments);
        }

        [Fact]
        public void Index_InstructorSelected_ShowsCourses()
        {
            // Arrange
            var instructor = SeedInstructorWithCourses();

            // Act
            var result = _controller.Index(instructor.ID, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Chemistry", model.Courses.First().Title);
        }

        [Fact]
        public void Index_CourseSelected_ShowsEnrollments()
        {
            // Arrange
            var instructor = SeedInstructorWithCourses();
            // Add a student and enrollment for the course
            var student = new Student { FirstMidName = "Test", LastName = "Student", EnrollmentDate = DateTime.Today };
            _context.Students.Add(student);
            _context.SaveChanges();
            _context.Enrollments.Add(new Enrollment { CourseID = 1050, StudentID = student.ID, Grade = Grade.A });
            _context.SaveChanges();

            // Act
            var result = _controller.Index(instructor.ID, 1050) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Enrollments);
            Assert.Single(model.Enrollments);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            // Act
            var result = _controller.Details(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsView()
        {
            // Arrange
            var instructor = SeedSimpleInstructor();

            // Act
            var result = _controller.Details(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Harui", model.LastName);
            Assert.Equal("Roger", model.FirstMidName);
        }

        #endregion

        #region Create

        [Fact]
        public void Create_GET_ReturnsView()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.Empty(model.CourseAssignments);
        }

        [Fact]
        public void Create_POST_ValidInstructorNoSelectedCourses_RedirectsToIndex()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01")
            };

            // Act
            var result = _controller.Create(instructor, null!);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Instructors);
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_AssignesCourses()
        {
            // Arrange
            var dept = new Department { Name = "Test", Budget = 100000, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            var course = new Course { CourseID = 1111, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "WithCourses",
                HireDate = DateTime.Parse("2020-01-01")
            };

            // Act
            var result = _controller.Create(instructor, new[] { "1111" });

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Instructors.Include(i => i.CourseAssignments).First();
            Assert.Single(saved.CourseAssignments);
            Assert.Equal(1111, saved.CourseAssignments.First().CourseID);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            // Arrange
            var instructor = new Instructor { FirstMidName = "Bad", LastName = "Data", HireDate = DateTime.Today };
            _controller.ModelState.AddModelError("Error", "Test");

            // Act
            var result = _controller.Create(instructor, null!) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Empty(_context.Instructors);
        }

        [Fact]
        public void Create_POST_SendsNotification()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Notify",
                LastName = "Test",
                HireDate = DateTime.Today
            };

            // Act
            _controller.Create(instructor, null!);

            // Assert
            var svc = new Services.NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
        }

        #endregion

        #region Edit GET

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructor = SeedInstructorWithCourses();

            // Act
            var result = _controller.Edit(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Abercrombie", model.LastName);
        }

        #endregion

        #region Delete

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_NotFound_ReturnsNotFound()
        {
            // Act
            var result = _controller.Delete(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsView()
        {
            // Arrange
            var instructor = SeedSimpleInstructor();

            // Act
            var result = _controller.Delete(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Harui", model.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            // Arrange
            var instructor = SeedInstructorWithCourses();

            // Act
            var result = _controller.DeleteConfirmed(instructor.ID);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_NullifiesDepartmentAdministrator()
        {
            // Arrange
            var instructor = SeedSimpleInstructor();
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = DateTime.Today,
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            // Need to reload instructor with OfficeAssignment for the Delete query
            instructor.OfficeAssignment = null;
            _context.SaveChanges();

            // Act
            _controller.DeleteConfirmed(instructor.ID);

            // Assert
            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.NotNull(updatedDept);
            Assert.Null(updatedDept!.InstructorID);
        }

        [Fact]
        public void DeleteConfirmed_SendsNotification()
        {
            // Arrange
            var instructor = SeedInstructorWithCourses();

            // Act
            _controller.DeleteConfirmed(instructor.ID);

            // Assert
            var svc = new Services.NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
        }

        #endregion
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestHelpers.CreateContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.Equal(8, _context.Students.Count());
