+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _sut;
+
+        public NotificationServiceTests()
+        {
+            TestHelpers.DrainNotificationQueue();
+            _sut = new NotificationService();
+        }
+
+        public void Dispose()
+        {
+            TestHelpers.DrainNotificationQueue();
+            _sut.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_FiveParamOverload_EnqueuesNotification()
+        {
+            // Act
+            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
+
+            // Assert
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("1", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Contains("John Doe", notification.Message);
+            Assert.Equal("Admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+        }
+
+        [Fact]
+        public void SendNotification_FourParamOverload_EnqueuesNotification()
+        {
+            // Act
+            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);
+
+            // Assert
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Course", notification.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Equal("UPDATE", notification.Operation);
+            Assert.Contains("Course", notification.Message);
+            Assert.Contains("42", notification.Message);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void SendNotification_NullUserName_DefaultsToSystem()
+        {
+            // Act
+            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);
+
+            // Assert
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void ReceiveNotification_EmptyQueue_ReturnsNull()
+        {
+            // Act
+            var result = _sut.ReceiveNotification();
+
+            // Assert
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void ReceiveNotification_MultipleItems_ReturnsFIFO()
+        {
+            // Arrange
+            _sut.SendNotification("A", "1", EntityOperation.CREATE);
+            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
+            _sut.SendNotification("C", "3", EntityOperation.DELETE);
+
+            // Act & Assert
+            var first = _sut.ReceiveNotification();
+            Assert.NotNull(first);
+            Assert.Equal("A", first.EntityType);
+
+            var second = _sut.ReceiveNotification();
+            Assert.NotNull(second);
+            Assert.Equal("B", second.EntityType);
+
+            var third = _sut.ReceiveNotification();
+            Assert.NotNull(third);
+            Assert.Equal("C", third.EntityType);
+
+            Assert.Null(_sut.ReceiveNotification());
+        }
+
+        [Theory]
+        [InlineData(EntityOperation.CREATE, "has been created")]
+        [InlineData(EntityOperation.UPDATE, "has been updated")]
+        [InlineData(EntityOperation.DELETE, "has been deleted")]
+        public void GenerateMessage_WithDisplayName_FormatsCorrectly(EntityOperation operation, string expectedFragment)
+        {
+            // Act
+            _sut.SendNotification("Student", "1", "John Doe", operation);
+
+            // Assert
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("Student 'John Doe'", notification.Message);
+            Assert.Contains(expectedFragment, notification.Message);
+        }
+
+        [Theory]
+        [InlineData(EntityOperation.CREATE, "has been created")]
+        [InlineData(EntityOperation.UPDATE, "has been updated")]
+        [InlineData(EntityOperation.DELETE, "has been deleted")]
+        public void GenerateMessage_WithoutDisplayName_UsesIdFormat(EntityOperation operation, string expectedFragment)
+        {
+            // Act
+            _sut.SendNotification("Course", "99", null, operation);
+
+            // Assert
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("Course (ID: 99)", notification.Message);
+            Assert.Contains(expectedFragment, notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_SetsCreatedAtToApproximateNow()
+        {
+            // Arrange
+            var before = DateTime.Now.AddSeconds(-1);
+
+            // Act
+            _sut.SendNotification("Test", "1", EntityOperation.CREATE);
+
+            // Assert
+            var after = DateTime.Now.AddSeconds(1);
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.InRange(notification.CreatedAt, before, after);
+        }
+
+        [Fact]
+        public void SendNotification_QueueCapEnforcement_TrimsOldEntries()
+        {
+            // Arrange - fill beyond 500 cap
+            for (int i = 0; i < 510; i++)
+            {
+                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
+            }
+
+            // Act - count remaining
+            int count = 0;
+            while (_sut.ReceiveNotification() != null)
+            {
+                count++;
+            }
+
+            // Assert - should be at most 500
+            Assert.True(count <= 500, $"Queue had {count} items, expected at most 500");
+        }
+
+        [Fact]
+        public void MarkAsRead_DoesNotThrow()
+        {
+            // Act & Assert (no-op, should not throw)
+            var exception = Record.Exception(() => _sut.MarkAsRead(1));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            // Act & Assert
+            var exception = Record.Exception(() => _sut.Dispose());
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_EmptyDisplayName_UsesIdFormat()
+        {
+            // Act
+            _sut.SendNotification("Student", "5", "   ", EntityOperation.CREATE);
+
+            // Assert
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("Student (ID: 5)", notification.Message);
+        }
+    }
+}
