public void GetNotifications_Max10Limit()
{
    // Arrange - enqueue 15 notifications directly
    // Use the controller's own notificationService field (protected, accessible since static queue)
    var svc = new Services.NotificationService();
    // Drain first to ensure clean state
    while (svc.ReceiveNotification() != null) { }

    for (int i = 0; i < 15; i++)
    {
        svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
    }

    // Act - immediately read (no other test should interleave)
    var result = _controller.GetNotifications();

    // Assert
    dynamic value = result.Value!;
    var type = value.GetType();
    var count = (int)type.GetProperty("count")!.GetValue(value);
    Assert.Equal(10, count);
}

