     public class SchoolContextTests : IDisposable
     {
         private readonly SchoolContext _context;

         public SchoolContextTests()
         {
             _context = TestHelpers.CreateContext();
         }

         public void Dispose()
         {
             _context.Dispose();
         }

         [Fact]
         public void CourseAssignment_HasCompositeKey()
         {
             // Arrange
             var dept = new Department { Name = "Test", Budget = 10000, StartDate = DateTime.Today };
             _context.Departments.Add(dept);
             _context.SaveChanges();

             var course = new Course { CourseID = 1, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
             _context.Courses.Add(course);

             var instructor = new Instructor { FirstMidName = "Test", LastName = "Instructor", HireDate = DateTime.Today };
             _context.Instructors.Add(instructor);
             _context.SaveChanges();

             var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
             _context.CourseAssignments.Add(assignment);
             _context.SaveChanges();

             // Act - look up by composite key
             var found = _context.CourseAssignments.Find(course.CourseID, instructor.ID);

             // Assert
             Assert.NotNull(found);
             Assert.Equal(course.CourseID, found!.CourseID);
             Assert.Equal(instructor.ID, found.InstructorID);
         }

         [Fact]
         public void TPH_StudentAndInstructor_SharePersonTable()
         {
             // Arrange
             var student = new Student { FirstMidName = "Test", LastName = "Student", EnrollmentDate = DateTime.Today };
             var instructor = new Instructor { FirstMidName = "Test", LastName = "Instructor", HireDate = DateTime.Today };
             _context.Students.Add(student);
             _context.Instructors.Add(instructor);
             _context.SaveChanges();

             // Act
             var people = _context.People.ToList();

             // Assert - both should appear in People table (TPH)
             Assert.Equal(2, people.Count);
             Assert.Contains(people, p => p is Student);
             Assert.Contains(people, p => p is Instructor);
         }

         [Fact]
         public void OfficeAssignment_OneToOne_WithInstructor()
         {
             // Arrange
             var instructor = new Instructor
             {
                 FirstMidName = "Test",
                 LastName = "Office",
                 HireDate = DateTime.Today,
                 OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
             };
             _context.Instructors.Add(instructor);
             _context.SaveChanges();

             // Act
             var loaded = _context.Instructors.Include(i => i.OfficeAssignment).Single(i => i.ID == instructor.ID);

             // Assert
             Assert.NotNull(loaded.OfficeAssignment);
             Assert.Equal("Room 101", loaded.OfficeAssignment!.Location);
             Assert.Equal(instructor.ID, loaded.OfficeAssignment.InstructorID);
         }

         [Fact]
         public void Course_Department_Relationship()
         {
             // Arrange
             var dept = new Department { Name = "Test", Budget = 10000, StartDate = DateTime.Today };
             _context.Departments.Add(dept);
             _context.SaveChanges();

             var course = new Course { CourseID = 5000, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
             _context.Courses.Add(course);
             _context.SaveChanges();

             // Act
             var loaded = _context.Courses.Include(c => c.Department).Single(c => c.CourseID == 5000);

             // Assert
             Assert.NotNull(loaded.Department);
             Assert.Equal("Test", loaded.Department.Name);
         }

         [Fact]
         public void DbSets_AreNotNull()
         {
             // Assert
             Assert.NotNull(_context.Courses);
             Assert.NotNull(_context.Enrollments);
             Assert.NotNull(_context.Departments);
             Assert.NotNull(_context.OfficeAssignments);
             Assert.NotNull(_context.CourseAssignments);
             Assert.NotNull(_context.People);
             Assert.NotNull(_context.Students);
             Assert.NotNull(_context.Instructors);
             Assert.NotNull(_context.Notifications);
         }

         [Fact]
         public void Department_NullableInstructorID_AllowsNull()
         {
             // Arrange
             var dept = new Department
             {
                 Name = "NoAdmin",
                 Budget = 50000,
                 StartDate = DateTime.Today,
                 InstructorID = null
             };
             _context.Departments.Add(dept);
             _context.SaveChanges();

             // Act
             var loaded = _context.Departments.Find(dept.DepartmentID);

             // Assert
             Assert.NotNull(loaded);
             Assert.Null(loaded!.InstructorID);
         }

         [Fact]
         public void Enrollment_NullableGrade()
         {
             // Arrange
             var student = new Student { FirstMidName = "Test", LastName = "Stud", EnrollmentDate = DateTime.Today };
             _context.Students.Add(student);
             var dept = new Department { Name = "Dept", Budget = 10000, StartDate = DateTime.Today };
             _context.Departments.Add(dept);
             _context.SaveChanges();

             var course = new Course { CourseID = 7777, Title = "NoGrade", Credits = 3, DepartmentID = dept.DepartmentID };
             _context.Courses.Add(course);
             _context.SaveChanges();

             var enrollment = new Enrollment { CourseID = course.CourseID, StudentID = student.ID, Grade = null };
             _context.Enrollments.Add(enrollment);
             _context.SaveChanges();

             // Act
             var loaded = _context.Enrollments.Find(enrollment.EnrollmentID);

             // Assert
             Assert.NotNull(loaded);
             Assert.Null(loaded!.Grade);
         }
     }
 }

